{"path": "/tmp/sv-7fb8216788e84c5986e695ccb762663d/RecipeHub/Components/Pages/SubmitRecipe.razor", "file_text": "@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Services
@inject RecipeService RecipeService
@inject NavigationManager Nav

<PageTitle>Submit a Recipe — RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Recipe submitted!</h4>
        <p>Your recipe "<strong>@_title</strong>" has been added. <a href="/recipes/@_category">View it now →</a></p>
    </div>
}
else
{
    <EditForm Model="@this" OnValidSubmit="HandleSubmit" FormName="submit-recipe" class="recipe-form">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" @bind-Value="_title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
            @if (_errors.ContainsKey("title"))
            {
                <div class="validation-message">@_errors["title"]</div>
            }
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" @bind-Value="_category" class="form-select">
                <option value="">-- Select a category --</option>
                @foreach (var cat in _categories)
                {
                    <option value="@cat">@cat</option>
                }
                <option value="Other">Other</option>
            </InputSelect>
            @if (_errors.ContainsKey("category"))
            {
                <div class="validation-message">@_errors["category"]</div>
            }
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" @bind-Value="_ingredients" class="form-control" rows="6"
                           placeholder="One ingredient per line&#10;e.g.,&#10;2 cups flour&#10;1 cup sugar&#10;3 eggs" />
            @if (_errors.ContainsKey("ingredients"))
            {
                <div class="validation-message">@_errors["ingredients"]</div>
            }
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" @bind-Value="_steps" class="form-control" rows="6"
                           placeholder="One step per line&#10;e.g.,&#10;Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
            @if (_errors.ContainsKey("steps"))
            {
                <div class="validation-message">@_errors["steps"]</div>
            }
        </div>

        <button type="submit" class="btn btn-primary btn-lg">Submit Recipe</button>
    </EditForm>
}

@code {
    private string _title = string.Empty;
    private string _category = string.Empty;
    private string _ingredients = string.Empty;
    private string _steps = string.Empty;
    private bool _submitted;
    private List<string> _categories = [];
    private Dictionary<string, string> _errors = new();

    protected override void OnInitialized()
    {
        _categories = RecipeService.GetCategories();
    }

    private void HandleSubmit()
    {
        _errors.Clear();

        if (string.IsNullOrWhiteSpace(_title))
            _errors["title"] = "Please enter a recipe title.";
        if (string.IsNullOrWhiteSpace(_category))
            _errors["category"] = "Please select a category.";
        if (string.IsNullOrWhiteSpace(_ingredients))
            _errors["ingredients"] = "Please list at least one ingredient.";
        if (string.IsNullOrWhiteSpace(_steps))
            _errors["steps"] = "Please describe at least one step.";

        if (_errors.Count > 0)
            return;

        RecipeService.AddRecipe(_title, _category, _ingredients, _steps);
        _submitted = true;
    }
}
"}

