namespace RecipeHub.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public List<int> Ratings { get; set; } = [];

    public double AverageRating =>
        Ratings.Count > 0 ? Math.Round(Ratings.Average(), 1) : 0;

    public int RatingCount => Ratings.Count;
}

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1,
                Title = "Classic Margherita Pizza",
                Category = "Italian",
                Description = "A simple and delicious pizza with fresh mozzarella, tomatoes, and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = ["Preheat oven to 475°F (245°C).", "Roll out dough on a floured surface.", "Spread crushed tomatoes over dough.", "Tear mozzarella and distribute evenly.", "Bake for 10-12 minutes until crust is golden.", "Top with fresh basil and drizzle with olive oil."],
                Ratings = [5, 4, 5, 4, 5]
            },
            new Recipe
            {
                Id = 2,
                Title = "Spaghetti Carbonara",
                Category = "Italian",
                Description = "Creamy pasta with pancetta, eggs, and Parmesan cheese.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Parmesan cheese", "Black pepper", "Salt"],
                Steps = ["Cook spaghetti in salted boiling water until al dente.", "Fry pancetta until crispy.", "Whisk eggs with grated Parmesan and pepper.", "Toss hot pasta with pancetta.", "Remove from heat and stir in egg mixture.", "Serve immediately with extra Parmesan."],
                Ratings = [5, 5, 4]
            },
            new Recipe
            {
                Id = 3,
                Title = "Chicken Tikka Masala",
                Category = "Indian",
                Description = "Tender chicken in a rich, spiced tomato-cream sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger", "Cumin", "Turmeric"],
                Steps = ["Marinate chicken in yogurt and spices for 1 hour.", "Grill or broil chicken until charred.", "Sauté onion, garlic, and ginger.", "Add tomato sauce and spices, simmer 15 minutes.", "Stir in cream and add chicken.", "Simmer 10 minutes and serve with rice."],
                Ratings = [5, 4, 5, 5]
            },
            new Recipe
            {
                Id = 4,
                Title = "Vegetable Pad Thai",
                Category = "Asian",
                Description = "Stir-fried rice noodles with vegetables, peanuts, and tangy sauce.",
                Ingredients = ["Rice noodles", "Tofu", "Bean sprouts", "Green onions", "Peanuts", "Lime", "Tamarind paste", "Fish sauce", "Sugar", "Garlic"],
                Steps = ["Soak rice noodles in warm water for 20 minutes.", "Mix tamarind paste, fish sauce, and sugar for sauce.", "Stir-fry tofu until golden.", "Add garlic and vegetables, cook 2 minutes.", "Add noodles and sauce, toss until coated.", "Serve with crushed peanuts and lime wedges."],
                Ratings = [4, 4, 5]
            },
            new Recipe
            {
                Id = 5,
                Title = "Beef Tacos",
                Category = "Mexican",
                Description = "Seasoned ground beef in warm tortillas with fresh toppings.",
                Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
                Steps = ["Brown ground beef in a skillet.", "Add taco seasoning and water, simmer 5 minutes.", "Warm tortillas in a dry pan.", "Fill tortillas with seasoned beef.", "Top with lettuce, tomato, cheese, sour cream, and salsa.", "Serve immediately."],
                Ratings = [4, 5, 4, 4]
            },
            new Recipe
            {
                Id = 6,
                Title = "Chocolate Lava Cake",
                Category = "Desserts",
                Description = "Rich chocolate cake with a molten center.",
                Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
                Steps = ["Preheat oven to 425°F (220°C).", "Melt chocolate and butter together.", "Whisk eggs and sugar until thick.", "Fold chocolate mixture into eggs.", "Add flour and vanilla, mix gently.", "Bake in greased ramekins for 12-14 minutes.", "Invert onto plates and serve immediately."],
                Ratings = [5, 5, 5, 4, 5]
            },
            new Recipe
            {
                Id = 7,
                Title = "Guacamole",
                Category = "Mexican",
                Description = "Fresh and creamy avocado dip with lime and cilantro.",
                Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
                Steps = ["Halve avocados and remove pits.", "Mash avocado to desired consistency.", "Stir in lime juice, salt, and diced onion.", "Fold in chopped cilantro, tomato, and jalapeño.", "Taste and adjust seasoning.", "Serve with tortilla chips."],
                Ratings = [5, 4, 5]
            },
            new Recipe
            {
                Id = 8,
                Title = "Miso Soup",
                Category = "Asian",
                Description = "Light and savory Japanese soup with tofu and seaweed.",
                Ingredients = ["Dashi stock", "Miso paste", "Silken tofu", "Wakame seaweed", "Green onions"],
                Steps = ["Bring dashi stock to a gentle simmer.", "Rehydrate wakame in water for 5 minutes.", "Dissolve miso paste in a ladle of warm broth.", "Add tofu cubes and wakame to the pot.", "Stir in dissolved miso — do not boil.", "Serve garnished with sliced green onions."],
                Ratings = [4, 4, 5, 4]
            }
        ];
        _nextId = 9;
    }

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetRecipeById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.Ratings.Add(stars);
        }
    }

    public void AddRecipe(string title, string category, string ingredients, string steps)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Description = $"A community-submitted {category.ToLowerInvariant()} recipe.",
            Ingredients = ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList()
        };
        _recipes.Add(recipe);
    }
}

