@page "/"
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>RecipeHub — Recipe Sharing Community</PageTitle>

<div class="hero">
    <h1>🍳 Welcome to RecipeHub</h1>
    <p class="lead">Discover, share, and rate recipes from around the world.</p>
</div>

<h2>Browse by Category</h2>
<div class="category-grid">
    @foreach (var category in _categories)
    {
        <a href="/recipes/@category" class="category-card">
            <span class="category-icon">@GetCategoryIcon(category)</span>
            <h3>@category</h3>
            <p>@RecipeService.GetRecipesByCategory(category).Count recipes</p>
        </a>
    }
</div>

<div class="cta-section mt-4">
    <h3>Have a recipe to share?</h3>
    <p>Join our community and submit your favorite recipes!</p>
    <a href="/submit" class="btn btn-primary btn-lg">Submit a Recipe →</a>
</div>

@code {
    private List<string> _categories = [];

    protected override void OnInitialized()
    {
        _categories = RecipeService.GetCategories();
    }

    private static string GetCategoryIcon(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Asian" => "🥢",
        "Mexican" => "🌮",
        "Desserts" => "🍰",
        _ => "🍽️"
    };
}

